import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        long[] vals = new long[N];

        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            long l = Long.parseLong(st.nextToken());
            long r = Long.parseLong(st.nextToken());
            vals[i] = (l + r) - 2L * i; // (l+r)/2 - i scaled by 2 to avoid fractions
        }

        Arrays.sort(vals);
        long median = vals[N / 2]; // median of the transformed values

        long cost = 0;
        for (long v : vals) {
            cost += Math.abs(v - median);
        }

        // Since we scaled by 2, actual cost is half of that
        System.out.println(cost / 2);
    }
}

