public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] l = new int[N], r = new int[N];
        for (int i = 0; i < N; i++) {
            l[i] = sc.nextInt();
            r[i] = sc.nextInt();
        }

        // Collect all candidate positions
        TreeSet<Integer> candSet = new TreeSet<>();
        for (int i = 0; i < N; i++) {
            candSet.add(l[i]);
            candSet.add(r[i]);
        }
        int[] cands = candSet.stream().mapToInt(x -> x).toArray();
        int M = cands.length;
        Map<Integer, Integer> idx = new HashMap<>();
        for (int i = 0; i < M; i++) idx.put(cands[i], i);

        long[] dp = new long[M];
        Arrays.fill(dp, Long.MAX_VALUE / 2);
        for (int j = 0; j < M; j++) dp[j] = Math.abs(cands[j] - l[0]);

        for (int i = 1; i < N; i++) {
            long[] ndp = new long[M];
            Arrays.fill(ndp, Long.MAX_VALUE / 2);
            int wi = r[i] - l[i];
            for (int jj = 0; jj < M; jj++) {
                int ai = cands[jj]; // left of rect i
                long cost = Math.abs(ai - l[i]);
                for (int kk = 0; kk < M; kk++) {
                    int ap = cands[kk]; // left of rect i-1
                    int wp = r[i-1] - l[i-1];
                    if (Math.max(ap, ai) <= Math.min(ap + wp, ai + wi)) {
                        ndp[jj] = Math.min(ndp[jj], dp[kk] + cost);
                    }
                }
            }
            dp = ndp;
        }

        long ans = Arrays.stream(dp).min().getAsLong();
        System.out.println(ans);
    }
}

