public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        long[] l = new long[N + 1];
        long[] r = new long[N + 1];
        for (int i = 1; i <= N; i++) {
            l[i] = fs.nextLong();
            r[i] = fs.nextLong();
        }

        // dpL[i]: minimum cost after processing 1..i, with connected common x chosen as left endpoint of feasible interval
        // dpR[i]: same, chosen as right endpoint
        // [L, R]: feasible x interval for the connected component of rectangles 1..i
        long L = l[1], R = r[1];
        long dpL = 0, dpR = 0;

        for (int i = 2; i <= N; i++) {
            long nL = Math.max(L, l[i]);
            long nR = Math.min(R, r[i]);

            long ndpL, ndpR;

            if (nL <= nR) {
                // Intervals overlap, feasible interval shrinks to intersection, no extra movement needed.
                ndpL = Math.min(
                        dpL + Math.abs(nL - L),
                        dpR + Math.abs(nL - R)
                );
                ndpR = Math.min(
                        dpL + Math.abs(nR - L),
                        dpR + Math.abs(nR - R)
                );
                L = nL;
                R = nR;
            } else {
                // Disjoint intervals: new feasible interval becomes [R, l[i]] or [r[i], L] merged as segment between them.
                // Since nL > nR, old [L,R] is completely left or right of new [l[i],r[i]].
                // The new feasible interval is [R, l[i]] if R < l[i], or [r[i], L] if r[i] < L.
                if (R < l[i]) {
                    long newLeft = R;
                    long newRight = l[i];
                    ndpL = Math.min(
                            dpL + Math.abs(newLeft - L),
                            dpR + Math.abs(newLeft - R)
                    );
                    ndpR = Math.min(
                            dpL + Math.abs(newRight - L),
                            dpR + Math.abs(newRight - R)
                    );
                    L = newLeft;
                    R = newRight;
                } else {
                    long newLeft = r[i];
                    long newRight = L;
                    ndpL = Math.min(
                            dpL + Math.abs(newLeft - L),
                            dpR + Math.abs(newLeft - R)
                    );
                    ndpR = Math.min(
                            dpL + Math.abs(newRight - L),
                            dpR + Math.abs(newRight - R)
                    );
                    L = newLeft;
                    R = newRight;
                }
            }

            dpL = ndpL;
            dpR = ndpR;
        }

        System.out.println(Math.min(dpL, dpR));
    }
}

