        long long ndpL, ndpR;

        if (nr < L) {
            // New interval is completely left of current intersection
            long long d = L - nr;
            ndpL = min(dpL + (L - nl), dpR + (R - nl));
            ndpR = min(dpL + d,        dpR + d);
            L = nl;
            R = nr;
        } else if (R < nl) {
            // New interval is completely right of current intersection
            long long d = nl - R;
            ndpL = min(dpL + d,        dpR + d);
            ndpR = min(dpL + (nr - L), dpR + (nr - R));
            L = nl;
            R = nr;
        } else {
            // They overlap; update intersection
            long long newL = max(L, nl);
            long long newR = min(R, nr);
            ndpL = min(dpL + max(0LL, L - nl), dpR + max(0LL, R - nl));
